  function dismissFavoriteHint(){try{localStorage.setItem(FAVORITE_HINT_KEY,'seen')}catch{}}
  function storedWorkspace(){try{const value=JSON.parse(localStorage.getItem(WORKSPACE_KEY)||'{}');return{exchange:ZychWorkspace.validExchange(value.exchange),marketId:typeof value.marketId==='string'?value.marketId:'',asset:typeof value.asset==='string'&&value.asset?value.asset:'BTC',quoteAsset:typeof value.quoteAsset==='string'&&value.quoteAsset?value.quoteAsset:'USDT',timeframe:TIMEFRAMES.includes(value.timeframe)?value.timeframe:'1h'}}catch{return{exchange:'binance',marketId:'',asset:'BTC',quoteAsset:'USDT',timeframe:'1h'}}}
  const workspacePreference=storedWorkspace(),initialMarket=MARKETS.find(market=>market.id===workspacePreference.marketId&&market.exchange===workspacePreference.exchange)||marketForAssetOnExchange(workspacePreference.asset,workspacePreference.exchange,workspacePreference.quoteAsset)||ZychWorkspace.unavailableMarket(workspacePreference.asset,workspacePreference.exchange,workspacePreference.quoteAsset);

