  const volumes=chart.addSeries?chart.addSeries(LightweightCharts.HistogramSeries,volumeOptions):chart.addHistogramSeries(volumeOptions);volumes.priceScale().applyOptions({scaleMargins:{top:.82,bottom:0}});
