  const watchSummary=()=>{const snapshots=state.watchlist.map(item=>ZychWatchlist.resolve(item,MARKETS)).filter(Boolean).map(market=>state.marketSnapshots[market.id]).filter(snapshot=>Number.isFinite(Number(snapshot?.changePercent))),gainers=snapshots.filter(snapshot=>Number(snapshot.changePercent)>0).length,losers=snapshots.filter(snapshot=>Number(snapshot.changePercent)<0).length;return{verified:snapshots.length,gainers,losers}};
  function renderWatchSummary(){const summary=watchSummary(),ratio=count=>summary.verified?`${count} (${(count/summary.verified*100).toFixed(0)}%)`:'—',total=document.getElementById('watchlist-total'),gainers=document.getElementById('watchlist-gainers'),losers=document.getElementById('watchlist-losers'),snapshots=state.watchlist.map(item=>ZychWatchlist.resolve(item,MARKETS)).filter(Boolean).map(market=>state.marketSnapshots[market.id]).filter(Boolean),timestamps=snapshots.map(snapshot=>Number(snapshot.snapshotTimestamp)).filter(Number.isFinite),updated=timestamps.length?Math.max(...timestamps):null,radarCount=document.getElementById('watchlist-radar-events'),radarStatus=document.getElementById('watchlist-radar-status');total.textContent=String(state.watchlist.length);gainers.textContent=ratio(summary.gainers);losers.textContent=ratio(summary.losers);applyDirection(gainers,summary.verified?1:null);applyDirection(losers,summary.verified?-1:null);document.getElementById('watchlist-updated').textContent=updated?radarTime(updated):'—';const radarAvailable=Boolean(watchRadarState?.lastSuccessfulFetch);radarCount.textContent=radarAvailable?String(watchRadarState.events.length):'—';radarStatus.textContent=radarAvailable?ZychRadarEvent.status(watchRadarState).label:ZychI18n.t('common.unavailable')}
